CREATE TABLE dag_document (id INTEGER PRIMARY KEY, schema TEXT NOT NULL);
CREATE TABLE dag_node (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES dag_document(id), ordinal INTEGER NOT NULL, native_id TEXT NOT NULL, name TEXT NOT NULL, abbreviation TEXT NOT NULL, icon TEXT NOT NULL, x REAL, y REAL, width REAL, height REAL, operator_kind TEXT, kind TEXT NOT NULL, x_ieee754_bits INTEGER NOT NULL, x_numeric_class TEXT NOT NULL, y_ieee754_bits INTEGER NOT NULL, y_numeric_class TEXT NOT NULL, width_ieee754_bits INTEGER NOT NULL, width_numeric_class TEXT NOT NULL, height_ieee754_bits INTEGER NOT NULL, height_numeric_class TEXT NOT NULL);
CREATE TABLE dag_edge (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES dag_document(id), ordinal INTEGER NOT NULL, native_id TEXT NOT NULL, source TEXT NOT NULL, target TEXT NOT NULL, route_style TEXT NOT NULL);
CREATE TABLE dag_io_port (id INTEGER PRIMARY KEY, node_id INTEGER NOT NULL REFERENCES dag_node(id), side TEXT NOT NULL, ordinal INTEGER NOT NULL, native_id TEXT NOT NULL, label TEXT NOT NULL, code TEXT NOT NULL, abbreviation TEXT NOT NULL, full_name TEXT NOT NULL, value_type TEXT, connected INTEGER, artifact_kind TEXT, cardinality TEXT NOT NULL, shape TEXT NOT NULL, visible INTEGER NOT NULL, resolved INTEGER);
CREATE TABLE dag_computation (id INTEGER PRIMARY KEY, node_id INTEGER NOT NULL REFERENCES dag_node(id), variadic_inputs INTEGER NOT NULL, variadic_outputs INTEGER NOT NULL);
CREATE TABLE dag_slider (id INTEGER PRIMARY KEY, node_id INTEGER NOT NULL REFERENCES dag_node(id), minimum REAL, maximum REAL, step REAL, value REAL, minimum_ieee754_bits INTEGER NOT NULL, minimum_numeric_class TEXT NOT NULL, maximum_ieee754_bits INTEGER NOT NULL, maximum_numeric_class TEXT NOT NULL, step_ieee754_bits INTEGER NOT NULL, step_numeric_class TEXT NOT NULL, value_ieee754_bits INTEGER NOT NULL, value_numeric_class TEXT NOT NULL);
CREATE TABLE dag_select (id INTEGER PRIMARY KEY, node_id INTEGER NOT NULL REFERENCES dag_node(id), selected_high_u32 INTEGER NOT NULL, selected_low_u32 INTEGER NOT NULL);
CREATE TABLE dag_select_option (id INTEGER PRIMARY KEY, select_id INTEGER NOT NULL REFERENCES dag_select(id), ordinal INTEGER NOT NULL, value TEXT NOT NULL);
CREATE TABLE dag_screen (id INTEGER PRIMARY KEY, node_id INTEGER NOT NULL REFERENCES dag_node(id));
CREATE TABLE dag_screen_media (id INTEGER PRIMARY KEY, screen_id INTEGER NOT NULL REFERENCES dag_screen(id), kind TEXT NOT NULL, source TEXT NOT NULL);
CREATE TABLE dag_note (id INTEGER PRIMARY KEY, node_id INTEGER NOT NULL REFERENCES dag_node(id), text TEXT NOT NULL);
CREATE TABLE dag_image (id INTEGER PRIMARY KEY, node_id INTEGER NOT NULL REFERENCES dag_node(id), source TEXT NOT NULL);
CREATE TABLE dag_preview (id INTEGER PRIMARY KEY, node_id INTEGER NOT NULL REFERENCES dag_node(id), content_variant TEXT NOT NULL);
CREATE TABLE dag_preview_scalar (id INTEGER PRIMARY KEY, preview_id INTEGER NOT NULL REFERENCES dag_preview(id), text TEXT NOT NULL);
CREATE TABLE dag_preview_image (id INTEGER PRIMARY KEY, preview_id INTEGER NOT NULL REFERENCES dag_preview(id), source TEXT NOT NULL);
CREATE TABLE dag_preview_tree (id INTEGER PRIMARY KEY, preview_id INTEGER NOT NULL REFERENCES dag_preview(id), value_id INTEGER NOT NULL REFERENCES dag_intrinsic_value(id));
CREATE TABLE dag_preview_expanded (id INTEGER PRIMARY KEY, preview_id INTEGER NOT NULL REFERENCES dag_preview(id), ordinal INTEGER NOT NULL, path TEXT NOT NULL);
CREATE TABLE dag_action (id INTEGER PRIMARY KEY, node_id INTEGER NOT NULL REFERENCES dag_node(id), label TEXT NOT NULL);
CREATE TABLE dag_export (id INTEGER PRIMARY KEY, node_id INTEGER NOT NULL REFERENCES dag_node(id), label TEXT NOT NULL, format TEXT NOT NULL);
CREATE TABLE dag_cluster (id INTEGER PRIMARY KEY, node_id INTEGER NOT NULL REFERENCES dag_node(id));
CREATE TABLE dag_app_instance (id INTEGER PRIMARY KEY, node_id INTEGER NOT NULL REFERENCES dag_node(id), instance_id TEXT NOT NULL, plugin_id TEXT NOT NULL, app_id TEXT NOT NULL, icon TEXT NOT NULL);
CREATE TABLE dag_node_property (id INTEGER PRIMARY KEY, node_id INTEGER NOT NULL REFERENCES dag_node(id), map_key TEXT NOT NULL, value_id INTEGER NOT NULL REFERENCES dag_property_value(id));
CREATE TABLE dag_edge_property (id INTEGER PRIMARY KEY, edge_id INTEGER NOT NULL REFERENCES dag_edge(id), map_key TEXT NOT NULL, value_id INTEGER NOT NULL REFERENCES dag_property_value(id));
CREATE TABLE dag_property_value (id INTEGER PRIMARY KEY, variant TEXT NOT NULL);
CREATE TABLE dag_property_boolean (id INTEGER PRIMARY KEY, value_id INTEGER NOT NULL REFERENCES dag_property_value(id), value INTEGER NOT NULL);
CREATE TABLE dag_property_number (id INTEGER PRIMARY KEY, value_id INTEGER NOT NULL REFERENCES dag_property_value(id), value REAL, value_ieee754_bits INTEGER NOT NULL, value_numeric_class TEXT NOT NULL);
CREATE TABLE dag_property_string (id INTEGER PRIMARY KEY, value_id INTEGER NOT NULL REFERENCES dag_property_value(id), value TEXT NOT NULL);
CREATE TABLE dag_property_array_element (id INTEGER PRIMARY KEY, array_id INTEGER NOT NULL REFERENCES dag_property_value(id), ordinal INTEGER NOT NULL, value_id INTEGER NOT NULL REFERENCES dag_property_value(id));
CREATE TABLE dag_property_object_member (id INTEGER PRIMARY KEY, object_id INTEGER NOT NULL REFERENCES dag_property_value(id), ordinal INTEGER NOT NULL, map_key TEXT NOT NULL, value_id INTEGER NOT NULL REFERENCES dag_property_value(id));
CREATE TABLE dag_intrinsic_value (id INTEGER PRIMARY KEY, variant TEXT NOT NULL);
CREATE TABLE dag_intrinsic_boolean (id INTEGER PRIMARY KEY, value_id INTEGER NOT NULL REFERENCES dag_intrinsic_value(id), value INTEGER NOT NULL);
CREATE TABLE dag_intrinsic_unsigned (id INTEGER PRIMARY KEY, value_id INTEGER NOT NULL REFERENCES dag_intrinsic_value(id), value_high_u32 INTEGER NOT NULL, value_low_u32 INTEGER NOT NULL);
CREATE TABLE dag_intrinsic_signed (id INTEGER PRIMARY KEY, value_id INTEGER NOT NULL REFERENCES dag_intrinsic_value(id), value INTEGER NOT NULL);
CREATE TABLE dag_intrinsic_float (id INTEGER PRIMARY KEY, value_id INTEGER NOT NULL REFERENCES dag_intrinsic_value(id), value REAL, value_ieee754_bits INTEGER NOT NULL, value_numeric_class TEXT NOT NULL);
CREATE TABLE dag_intrinsic_string (id INTEGER PRIMARY KEY, value_id INTEGER NOT NULL REFERENCES dag_intrinsic_value(id), value TEXT NOT NULL);
CREATE TABLE dag_intrinsic_bytes (id INTEGER PRIMARY KEY, value_id INTEGER NOT NULL REFERENCES dag_intrinsic_value(id), value BLOB NOT NULL);
CREATE TABLE dag_intrinsic_array_element (id INTEGER PRIMARY KEY, array_id INTEGER NOT NULL REFERENCES dag_intrinsic_value(id), ordinal INTEGER NOT NULL, value_id INTEGER NOT NULL REFERENCES dag_intrinsic_value(id));
CREATE TABLE dag_intrinsic_object_member (id INTEGER PRIMARY KEY, object_id INTEGER NOT NULL REFERENCES dag_intrinsic_value(id), ordinal INTEGER NOT NULL, name TEXT NOT NULL, value_id INTEGER NOT NULL REFERENCES dag_intrinsic_value(id));
CREATE TABLE dag_port_default (id INTEGER PRIMARY KEY, port_id INTEGER NOT NULL REFERENCES dag_io_port(id), value_id INTEGER NOT NULL REFERENCES dag_intrinsic_value(id));
CREATE TABLE dag_port_value (id INTEGER PRIMARY KEY, port_id INTEGER NOT NULL REFERENCES dag_io_port(id), value_id INTEGER NOT NULL REFERENCES dag_intrinsic_value(id));
